-- Provision the fixed canonical Binary pair universe missing from production D1.
-- This data-only migration preserves the existing Gate2BinaryConfiguration version model.
-- It inserts only absent pair/duration tuples whose ACTIVE D1 market and binance-spot
-- capability rows are present. Existing and historical rows are left untouched.

INSERT INTO "Gate2BinaryConfiguration" ("id","pair","durationSeconds","payoutRate","lossRate","minStake","maxStake","settlementDelaySeconds","version","enabled","createdAt","updatedAt")
SELECT 'f3b00000-0000-4000-8000-000000000001','MASKUSDT',30,'0.85','0','1','1000',0,1,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM "Gate2BinaryConfiguration" WHERE "pair"='MASKUSDT' AND "durationSeconds"=30)
AND EXISTS (SELECT 1 FROM "MarketPair" p JOIN "MarketAsset" a ON a."id"=p."baseAssetId" JOIN "MarketAsset" q ON q."id"=p."quoteAssetId" WHERE p."symbol"='MASKUSDT' AND p."category"='crypto' AND p."status"='ACTIVE' AND a."status"='ACTIVE' AND q."status"='ACTIVE' AND (SELECT COUNT(*) FROM "MarketAssetCapability" c WHERE c."assetId" IN (p."baseAssetId",p."quoteAssetId") AND c."status"='ACTIVE' AND c."tradingEnabled"=1)=2) AND EXISTS (SELECT 1 FROM "MarketProviderSymbol" ps JOIN "MarketProviderConfig" pc ON pc."id"=ps."providerId" JOIN "MarketPair" p ON p."id"=ps."pairId" WHERE p."symbol"='MASKUSDT' AND ps."enabled"=1 AND pc."key"='binance-spot' AND pc."status"='ACTIVE');

